    const result = await handle(basePayload, { ...baseConfig, fetch })
    expect(result.openaiCompletionId).toBe('chatcmpl-123')
    expect(result.githubCommentId).toBe(1)
    expect(calls).toHaveLength(2)
  })

  it('verifies HMAC-SHA256 signature from X-Hub-Signature-256 header', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.openai.com/v1/chat/completions') {
        return jsonResponse(TARGET_ENDPOINTS[0].response)
      }
      return jsonResponse(TARGET_ENDPOINTS[1].response)
    })

    const crypto = await import('node:crypto')
    const secret = 'test-secret'
    const body = JSON.stringify(basePayload)
    const signature = `sha256=${crypto.createHmac('sha256', secret).update(body).digest('hex')}`

    const payloadWithSig = { ...basePayload, x_hub_signature_256: signature }
    await handle(payloadWithSig, { ...baseConfig, fetch })
    expect(calls.length).toBe(2)
  })

  it('throws on missing pull_request.title', async () => {
